from fastapi import FastAPI

app = FastAPI()

@app.vibe("/vibe")
async def vibe_root():
    return {"message": "vibe check"}

def test_vibe_route():
    # We just want to see if the route is registered with the VIBE method
    for route in app.routes:
        if getattr(route, "path", None) == "/vibe":
            assert route.methods == {"VIBE"}
            print("Route registered correctly with VIBE method")
            return
    raise AssertionError("Route /vibe not found")

if __name__ == "__main__":
    try:
        test_vibe_route()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)
